int
heap_oos_validate_disk_record (THREAD_ENTRY *thread_p, const OID *class_oid, const RECDES *record)
{
  if (OID_IS_ROOTOID (class_oid) || (record != nullptr && record->type == REC_ASSIGN_ADDRESS))
    {
      return NO_ERROR;
    }
  if (!heap_recdes_has_valid_header (record))
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_OOS_BAD_INLINE_HEADER, 3, OID_AS_ARGS (&oid_Null_oid));
      return ER_HEAP_OOS_BAD_INLINE_HEADER;
    }
  if (!heap_recdes_contains_oos (record))
    {
      return NO_ERROR;
    }

  int cache_index = -1;
  RECDES view = *record;
  OR_CLASSREP *repr = heap_classrepr_get (thread_p, class_oid, nullptr, or_rep_id (&view), &cache_index);
  if (repr == nullptr)
    {
      return er_errid () == NO_ERROR ? ER_FAILED : er_errid ();
    }
  int error = NO_ERROR;
  bool found_oos = false;
  const int table_entries = (record->length - OR_HEADER_SIZE (record->data)) / OR_GET_OFFSET_SIZE (record->data);
  if (repr->n_variable < 1 || repr->n_variable >= table_entries)
    {
      error = ER_HEAP_OOS_BAD_INLINE_HEADER;
    }
  for (int i = 0; i < repr->n_attributes && error == NO_ERROR; ++i)
    {
      const OR_ATTRIBUTE &attr = repr->attributes[i];
      if (attr.is_fixed)
	{
	  continue;
	}
      int entry = 0;
      if (attr.location < 0 || attr.location >= repr->n_variable
	  || heap_recdes_get_var_offset_entry (record, attr.location, &entry) != NO_ERROR)
	{
	  error = ER_HEAP_OOS_BAD_INLINE_HEADER;
	  break;
	}
      if (OR_IS_OOS (entry))
	{
	  oos_chain_ref ref;
	  DB_BIGINT length;
	  found_oos = true;
	  error = heap_oos_parse_inline_ref (record, attr.location, &ref, &length);
	}
    }
  heap_classrepr_free_and_init (repr, &cache_index);
  if (error != NO_ERROR || !found_oos)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_OOS_BAD_INLINE_HEADER, 3, OID_AS_ARGS (&oid_Null_oid));
      return ER_HEAP_OOS_BAD_INLINE_HEADER;
    }

  direction = HEAP_DIRECTION_BOTH;

  while (direction != HEAP_DIRECTION_NONE)
    {
      /*
       * Don't include the desired object again, forwarded instances, nor
       * instances that belong to other classes
       */

      /* Optional prefetch copies raw page records while holding the heap latch.
       * Skip OOS neighbors; ordinary fetch expands them before publication. */
      /* Check to the right */
      if (direction == HEAP_DIRECTION_RIGHT || direction == HEAP_DIRECTION_BOTH)
	{
	  scan = spage_next_record (pgptr, &right_slotid, prefetch->recdes, COPY);
	  if (scan == S_SUCCESS && spage_get_record_type (pgptr, right_slotid) == REC_HOME
	      && (OID_IS_ROOTOID (class_oid)
		  || (heap_recdes_has_valid_header (prefetch->recdes) && !heap_recdes_contains_oos (prefetch->recdes))))
	    {
	      prefetch->mobjs->num_objs++;
	      COPY_OID (&((*prefetch->obj)->class_oid), class_oid);
	      (*prefetch->obj)->oid.volid = oid->volid;
	      (*prefetch->obj)->oid.pageid = oid->pageid;
	      (*prefetch->obj)->oid.slotid = right_slotid;
	      (*prefetch->obj)->length = prefetch->recdes->length;
	      (*prefetch->obj)->offset = *prefetch->offset;
	      (*prefetch->obj)->operation = LC_FETCH;
	      (*prefetch->obj) = LC_NEXT_ONEOBJ_PTR_IN_COPYAREA (*prefetch->obj);
	      round_length = DB_ALIGN (prefetch->recdes->length, HEAP_MAX_ALIGN);
	      *prefetch->offset += round_length;
	      prefetch->recdes->data += round_length;
	      prefetch->recdes->area_size -= (round_length + sizeof (*(*prefetch->obj)));
	    }
	  else if (scan != S_SUCCESS)
	    {
	      /* Stop prefetching objects from the right */
	      direction = ((direction == HEAP_DIRECTION_BOTH) ? HEAP_DIRECTION_LEFT : HEAP_DIRECTION_NONE);
	    }
	}

      /* Check to the left */
      if (direction == HEAP_DIRECTION_LEFT || direction == HEAP_DIRECTION_BOTH)
	{
	  scan = spage_previous_record (pgptr, &left_slotid, prefetch->recdes, COPY);
	  if (scan == S_SUCCESS && left_slotid != HEAP_HEADER_AND_CHAIN_SLOTID
	      && spage_get_record_type (pgptr, left_slotid) == REC_HOME
	      && (OID_IS_ROOTOID (class_oid)
		  || (heap_recdes_has_valid_header (prefetch->recdes) && !heap_recdes_contains_oos (prefetch->recdes))))
	    {
	      prefetch->mobjs->num_objs++;
	      COPY_OID (&((*prefetch->obj)->class_oid), class_oid);
	      (*prefetch->obj)->oid.volid = oid->volid;
	      (*prefetch->obj)->oid.pageid = oid->pageid;
	      (*prefetch->obj)->oid.slotid = left_slotid;
	      (*prefetch->obj)->length = prefetch->recdes->length;
	      (*prefetch->obj)->offset = *prefetch->offset;
	      (*prefetch->obj)->operation = LC_FETCH;
	      (*prefetch->obj) = LC_NEXT_ONEOBJ_PTR_IN_COPYAREA (*prefetch->obj);
	      round_length = DB_ALIGN (prefetch->recdes->length, HEAP_MAX_ALIGN);
	      *prefetch->offset += round_length;
	      prefetch->recdes->data += round_length;
	      prefetch->recdes->area_size -= (round_length + sizeof (*(*prefetch->obj)));
	    }
	  else if (scan != S_SUCCESS)
	    {
	      /* Stop prefetching objects from the right */
	      direction = ((direction == HEAP_DIRECTION_BOTH) ? HEAP_DIRECTION_RIGHT : HEAP_DIRECTION_NONE);
	    }
	}
    }

  pgbuf_unfix_and_init (thread_p, pgptr);

  return ret;
}

